INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64210481', 64210481, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'UPT Logam', 'Belanja Jasa Konsultansi Berorientasi Bidang-Perindustrian dan Perdagangan Belanja Jasa Manajemen Sosmed', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 18084000, 'June 2026', 'BLUD', 1, 1, 'paket', 'Lingkup Tugas yang harus dilaksanakan oleh Jasa Konsultansi Berorientasi Bidang-Perindustrian dan Perdagangan untuk Jasa Manajemen Sosmed, adalah sebagai berikut : Meningkatkan Partisipasi Publik : Media sosial dapat menjadi alat yang efektif untuk meningkatkan partisipasi publik dalam proses pembuatan keputusan pemerintah. Melalui jejak pendapat online, forum diskusi, dan pengumpulan umpan balik, pemerintah dapat melibatkan masyarakat dalam pembentukan kebijakan yang lebih inklusif dan responsif terhadap kebutuhan mereka. Mengedukasi Masyarakat : Manajemen media sosial memungkinkan pemerintah untuk mengedukasi masyarakat tentang isu-isu penting, kebijakan publik, dan layanan pemerintah. Dengan menyediakan konten yang informatif dan relevan, seperti infografis, video, dan artikel, pemerintah dapat membantu masyarakat memahami hak, kewajiban, dan sumber daya yang tersedia bagi mereka. Meningkatkan Transparansi : Salah satu tujuan utama dari manajemen media sosial bagi organisasi pemerintah adalah untuk meningkatkan transparansi. Dengan berbagi informasi tentang kebijakan, program, dan kegiatan pemerintah secara terbuka di media sosial, pemerintah dapat membangun kepercayaan dengan masyarakat, memberikan pemahaman yang lebih baik tentang proses pengambilan keputusan, dan memperkuat hubungan antara pemerintah dan masyarakat. Krisis dan Manajemen Darurat : Manajemen media sosial juga penting dalam situasi krisis dan darurat. Dalam keadaan seperti bencana alam atau kejadian darurat lainnya, pemerintah dapat menggunakan media sosial untuk menyebarkan informasi penting, memberikan instruksi evakuasi, dan memberikan bantuan kepada warga yang terdampak. Meningkatkan Citra Pemerintah : Manajemen media sosial dapat membantu meningkatkan citra pemerintah dengan menyampaikan pesan-pesan yang positif, menghargai prestasi, dan menanggapi kekhawatiran masyarakat dengan cepat dan efektif. dengan membangun kehadiran online yang kuat dan responsif, pemerintah dapat memperkuat legitimasinya di mata masyarakat.', 'ada dalam KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1380163);
