INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64190634', 64190634, 'analyze_legacy', 'Kab. Probolinggo', 'kabkota', 'Puskesmas Klenang Kidul', 'Belanja Makanan dan Minuman Jamuan Tamu_Pelayanan dan Penunjang Pelayanan BLUD_Puskesmas Klenang Kidul', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kab.)', 2000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Pengadaan ini bertujuan untuk menjamin tersedianya konsumsi yang layak, higienis, dan tepat waktu guna menunjang kelancaran kegiatan, menjaga profesionalitas institusi, serta mendukung efektivitas komunikasi dan koordinasi antar pihak terkait.', 'Spesifikasi belanja meliputi penyediaan makanan dan minuman jamuan tamu yang memenuhi standar kesehatan dan keamanan pangan, terdiri atas makanan ringan dan/atau makanan siap saji, kue basah dan kue kering, nasi kotak atau snack box sesuai kebutuhan kegiatan, serta minuman berupa air mineral kemasan, teh, kopi, gula, dan perlengkapan pendukung penyajian lainnya. Seluruh bahan makanan harus dalam kondisi segar, layak konsumsi, bersih, memiliki kemasan yang baik, tidak kedaluwarsa, serta disiapkan oleh penyedia yang memenuhi persyaratan higiene dan sanitasi pangan, dengan porsi dan variasi yang disesuaikan dengan jumlah peserta dan jenis kegiatan di BLUD Puskesmas Klenang Kidul.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1380960);
