INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64190706', 64190706, 'analyze_legacy', 'Kab. Probolinggo', 'kabkota', 'Puskesmas Klenang Kidul', 'Belanja Pakaian Batik_Pelayanan dan Penunjang Pelayanan BLUD_Puskesmas Klenang Kidul', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kab.)', 15000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Pengadaan ini dimaksudkan untuk memenuhi kebutuhan seragam kerja yang seragam, rapi, dan sesuai ketentuan, sehingga menunjang kedisiplinan, identitas institusi, serta profesionalisme pegawai dalam melaksanakan pelayanan kesehatan kepada masyarakat maupun kegiatan administrasi dan penunjang lainnya.', 'Spesifikasi pekerjaan meliputi penyediaan pakaian batik dengan bahan kain batik yang berkualitas baik, nyaman dipakai, tidak mudah luntur, dan sesuai standar penggunaan seragam kerja harian, seperti kain katun atau campuran katun yang menyerap keringat. Pakaian disediakan dalam berbagai ukuran sesuai kebutuhan pegawai, dengan desain dan motif batik yang seragam serta mencerminkan identitas instansi, dilengkapi proses penjahitan yang rapi dan kuat, sehingga layak digunakan untuk menunjang aktivitas pelayanan dan penunjang pelayanan di UPT Puskesmas Klenang Kidul.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1382512);
