INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64191449', 64191449, 'analyze_legacy', 'Kab. Probolinggo', 'kabkota', 'Puskesmas Klenang Kidul', 'Belanja Pemeliharaan Alat AngkutanAlat Angkutan Darat Bermotor Kendaraan Bermotor Khusus_Pelayanan dan Penunjang Pelayanan BLUD_Puskesmas Klenang Kidul', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kab.)', 15000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', 'Belanja Pemeliharaan Alat Angkutan Darat Bermotor Kendaraan Bermotor Khusus pada Pelayanan dan Penunjang Pelayanan BLUD Puskesmas Klenang Kidul merupakan kegiatan pemeliharaan rutin dan berkala terhadap kendaraan bermotor khusus milik puskesmas yang digunakan untuk mendukung pelayanan kesehatan dan kegiatan operasional lapangan, meliputi pemeriksaan kondisi kendaraan, perawatan mesin, sistem kelistrikan, sistem pengereman, suspensi, ban, serta perbaikan ringan hingga sedang agar kendaraan selalu dalam kondisi laik jalan, aman, dan siap digunakan sesuai standar operasional pelayanan kesehatan.', 'Spesifikasi pekerjaan dan bahan yang diperlukan dalam belanja ini meliputi jasa servis kendaraan bermotor khusus serta pengadaan suku cadang dan bahan pendukung, antara lain oli mesin dan oli transmisi, filter oli dan filter udara, minyak rem, coolant radiator, kampas rem, busi, aki, fan belt, ban dalam dan luar bila diperlukan, pelumas pendukung, cairan pembersih mesin, serta komponen kecil lainnya yang sesuai dengan jenis dan spesifikasi teknis kendaraan, dengan ketentuan seluruh bahan dan suku cadang yang digunakan memenuhi standar pabrikan dan mendukung keandalan kendaraan operasional Puskesmas Klenang Kidul.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1383119);
