INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64231236', 64231236, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'KANTOR PERTANAHAN KAB GORONTALO', 'Langganan Bandwith', 'Jasa Lainnya', 'Pengadaan Langsung', 'Gorontalo, Gorontalo (Kab.)', 225319000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, TAHUN, @ 225319000 )', 'Berlangganan internet Telkom artinya berlangganan layanan internet dari Telkom Indonesia, terutama melalui produk utamanya yaitu IndiHome (internet rumah, telepon, TV Interaktif) atau Telkomsel Orbit (WiFi rumah pakai jaringan seluler), serta solusi korporat seperti ASTINet, dengan berbagai pilihan paket kecepatan, fitur hiburan, dan layanan tambahan sesuai kebutuhan, seringkali menggunakan jaringan fiber optik atau 4G/5G untuk koneksi cepat dan stabil di rumah atau bisnis.', 'Spesifikasi berlangganan Astinet Telkom mencakup layanan internet dedicated untuk bisnis dengan kecepatan mulai dari 1 Mbps hingga 1 Gbps, rasio bandwidth simetris (1:1) atau asimetris (1:2/1:4), IP Statis, jaminan SLA hingga 99.5%, dan fitur pemantauan real-time (MRTG). Pilihan paketnya bervariasi, dari Astinet Dedicated untuk kebutuhan besar, Astinet Fit (1:2), hingga Astinet Lite (1:4) yang lebih terjangkau, dilengkapi IP Publik, cocok untuk UKM, kantor, hingga perusahaan besar.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1385203);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64190187', 64190187, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA JAKARTA SMART CITY', 'Pengadaan Tenaga Ahli Manajer Kajian dan Analisa Data Pengembangan Produk dan Layanan Februari 1 #1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 18425000, 'January 2026', 'APBD', 1, 1, '1 orang x 1 bulan', '1. Mengelola dan mengoordinasikan kegiatan analisis data serta kajian strategis; 2. Mengelola dan memimpin tim untuk memastikan seluruh alur kerja analisis data berjalan efektif, terukur, dan sesuai standar organisasi; 3. Mendistribusikan tugas dan prioritas pekerjaan sesuai kapasitas, urgensi isu kota, serta kebutuhan organisasi; 4. Mengidentifikasi risiko operasional dan menyediakan dukungan/solusi untuk memastikan pekerjaan tim tidak terhambat; 5. Menilai kelayakan usulan proyek data dari pihak internal/eksternal dan merekomendasikan keputusan berdasarkan insight strategis; 6. Berkolaborasi dengan lintas divisi untuk memastikan sinkronisasi kebutuhan data, alur kerja, dan hasil analisis; 7. Menjembatani komunikasi teknis antara tim data dan pemangku kepentingan non-teknis; 8. Mengelola permintaan data dan analisis dari perangkat daerah dengan memastikan relevansi, prioritas, dan sumber daya yang tersedia; dan 9. Menyusun laporan strategis, executive summary, dan bahan presentasi untuk pimpinan, dan lain sebagainya.', 'Tenaga Ahli Utama Spesifikasi: S1 Pengalaman Minimal 6 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1385204);
