INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64173802', 64173802, 'analyze_legacy', 'Kementerian Hukum', 'central', 'BADAN PEMBINAAN HUKUM NASIONAL', 'Pengadaan Belanja Bahan Kegiatan Pembinaan dan Pengelolaan SDM Dukungan Penyelenggaraan Tugas dan Fungsi Unit pada kantor Badan Pembinaan Hukum Nasional Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 48770000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Biaya konsumsi makan kegiatan ( 460, OK, @ 57000 ); 2. Biaya penggandaan dan penjilidan ( 1, PKT, @ 200000 ); 3. Biaya Konsumsi Kudapan Rapat ( 50, OK, @ 24000 ); 4. Biaya penggandaan dan penjilidan ( 1, PKT, @ 200000 ); 5. Biaya pembuatan plakat penghargaan pegawai ( 3, Paket, @ 600000 ); 6. Biaya pembuatan piagam penghargaan pegawai (cetak bingkai) ( 3, Paket, @ 250000 ); 7. Biaya konsumsi kudapan kegiatan ( 25, OK, @ 24000 ); 8. Biaya konsumsi makan rapat ( 50, OK, @ 57000 ); 9. Biaya konsumsi kudapan kegiatan ( 230, OK, @ 24000 ); 10. Biaya konsumsi kudapan rapat ( 40, OK, @ 22500 ); 11. Biaya penggandaan dan penjilidan ( 1, PKT, @ 200000 ); 12. Biaya konsumsi makan rapat ( 50, OK, @ 57000 ); 13. Biaya penggandaan dan penjilidan ( 1, PKT, @ 680000 ); 14. Biaya pembuatan spanduk/banner ( 2, buah, @ 225000 ); 15. Biaya konsumsi kudapan rapat ( 75, OK, @ 20000 ); 16. Biaya konsumsi makan rapat ( 50, OK, @ 57000 );', 'spesifikasi sesuai permintaan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1389077);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64215008', 64215008, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'UPT Logam', 'Belanja Jasa Tenaga Keamanan Jasa Keamanan Gedung 2', 'Jasa Lainnya', 'E-Purchasing', 'DI Yogyakarta, Yogyakarta (Kota)', 455938340, 'December 2025', 'APBD', 1, 1, '12 bulan', 'Lingkup pekerjaan jasa tenaga keamanan yang akan dilaksanakan di Gedung Pusat Desain Industri Nasional (PDIN) mencakup beberapa aspek utama, sebagai berikut: Pengamanan Area Gedung 1. Melaksanakan pengawasan dan pengamanan terhadap seluruh area gedung, baik di dalam maupun di sekitar lingkungan gedung, termasuk lobi, ruang kerja, ruang rapat, fasilitas umum, area parkir, dan akses masuk/keluar. 2. Memastikan tidak ada aktivitas yang mencurigakan atau dapat mengganggu operasional di area gedung. Pengelolaan Keamanan Akses 1. Melakukan pemeriksaan terhadap setiap orang yang masuk ke gedung, termasuk tamu, mitra kerja, dan karyawan, dengan prosedur yang telah ditentukan. 2. Mengelola pencatatan dan pendataan kunjungan tamu, barang, dan kendaraan yang keluar/masuk ke lingkungan gedung. Penanganan Keadaan Darurat 1. Siaga dalam menghadapi situasi darurat, seperti kebakaran, bencana alam, dan ancaman keamanan lainnya, sesuai dengan protokol keamanan yang berlaku. 2. Memberikan bantuan evakuasi dan koordinasi dengan pihak terkait (pemadam kebakaran, polisi, dan tenaga medis) jika terjadi keadaan darurat. Pengawasan Peralatan dan Fasilitas 1. Memastikan bahwa peralatan keamanan, seperti CCTV, alarm, dan peralatan pemadam kebakaran, berfungsi dengan baik. 2. Melakukan pemeriksaan rutin terhadap fasilitas keamanan dan melaporkan kerusakan atau kebutuhan perbaikan. Patroli Rutin 1. Melaksanakan patroli secara berkala di seluruh area gedung untuk memastikan tidak adanya potensi gangguan keamanan. 2. Mengawasi titik-titik rawan di sekitar gedung, seperti area parkir, akses pintu belakang, dan tempat yang minim penerangan. Pelaporan dan Dokumentasi 1. Menyusun laporan harian, mingguan, dan bulanan terkait kegiatan keamanan yang telah dilaksanakan, termasuk kejadian khusus atau insiden yang terjadi. 2. Mencatat dan melaporkan segera kepada pengelola gedung apabila ditemukan hal-hal yang mencurigakan atau berpotensi menimbulkan risiko.', 'ada dalam KAK/Speksifikasi Teknis', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1389078);
